# Entry-point prerequisite, before CUDA initialization:
import os
os.environ.setdefault('CUBLAS_WORKSPACE_CONFIG', ':4096:8')

# Logical adapter implementation; helpers use the supplied host interfaces.
class DiagnosisProbe:
    def __init__(self, view, device):
        self.view, self.device = view, device

    def run_full_diagnosis(self, train_loader):
        state = capture_module_modes_rng_and_numerical_settings(self.view.model)
        metrics, definitions = {}, {}
        try:
            self.view.model.eval()
            readiness = check_cuda_configuration_without_late_repair()
            if not readiness.ok:
                return missing_result(readiness.reason)
            cached = cache_at_most_ten_batches(train_loader)
            events = identify_unambiguous_training_events(cached, self.view.user_train)
            events = select_at_most_32_users_two_prefixes_each(events, seed=42)
            checks = run_bounded_contract_preflight(self.view, events)
            record_checks_and_available_export_parity(checks)
            if checks.contract_failure:
                return blocked_sensitivity_result(checks)
            with inference_mode():
                for event in events:
                    last = largest_occupied_index(event.sequence)
                    candidates = fixed_training_only_candidates(event, maximum=100, seed=42)
                    clean = score_at(self.view, event.sequence, last, candidates)
                    assert_identity_edit_matches(clean)
                    edited = permute_interior_preserving_endpoint_padding_and_multiset(event)
                    changed = score_at(self.view, edited, last, candidates)
                    record_rank_bounds_margin_deltas_and_coverage(clean, changed)
            average_repeats_and_prefixes_within_user()
            summarize_with_explicit_denominators_and_missing_reasons()
        finally:
            restore_state(state)
        return {'metrics': metrics, 'metric_definitions': definitions}


def diagnosis_interpreter_prompt(raw_diagnosis):
    return evidence_grounded_prompt(
        raw_diagnosis['metrics'], raw_diagnosis['metric_definitions'],
        scope='Training sensitivity; selection remains host macro validation HR@10')
